import{_ as r,o as e,c as a,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"用户手册","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/index.md","filePath":"zh-CN/user-guide/index.md","lastUpdated":1785993908000}'),s={name:"zh-CN/user-guide/index.md"};function n(i,t,l,h,g,d){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="用户手册" tabindex="-1">用户手册 <a class="header-anchor" href="#用户手册" aria-label="Permalink to &quot;用户手册&quot;">​</a></h1><p>Lertaro 是一款为 Windows 打造的、键盘优先的极速文件检索启动器。它在后台索引你的本地磁盘(NTFS 和 ReFS 通过各自的变更日志，其他文件系统则直接监听变化)及网络共享，让你能在极短时间内跳转到任意文件、文件夹或应用程序。</p><p>本手册涵盖日常使用所需的一切：</p><ul><li><strong><a href="./getting-started.html">快速上手</a></strong> —— 安装 Lertaro，了解它的三种搜索窗口(主窗口/快速窗口/内嵌窗口)。</li><li><strong><a href="./search-syntax.html">搜索语法</a></strong> —— 模糊匹配、排除/精确/前缀/后缀操作符、或组、盘符定向、路径模式，以及中文文件名的拼音别名匹配。</li><li><strong><a href="./hotkeys.html">热键</a></strong> —— 每一个可配置快捷键与硬编码按键，及其默认绑定。</li><li><strong><a href="./actions-and-preview.html">动作菜单与预览</a></strong> —— 类右键菜单的动作列表，以及 QuickLook 预览窗口。</li><li><strong><a href="./instant-answers.html">即时答案与关键词功能</a></strong> —— 计算器、环境变量、运行命令这些快捷方式，以及进程管理、窗口切换器、浏览器数据、设置搜索、网页搜索这类关键词触发的插件。</li><li><strong><a href="./cli.html">命令行搜索（lff）</a></strong> —— 可以在终端里使用的、fzf 风格的命令行伴侣工具。</li><li><strong><a href="./uri-protocol.html">URI 协议（lertaro://）</a></strong> —— 通过一个链接、别的程序或脚本，直接跳转到某次搜索或某项具体设置。</li><li><strong><a href="./file-manager-support.html">支持的文件管理器</a></strong> —— Lertaro 可以嵌入、触发快速导航、或检测当前文件夹的文件管理器和文件选择对话框都有哪些。</li><li><strong><a href="./settings/">设置项参考</a></strong> —— 每一个设置页面、每一个 Tab、每一项设置，逐条列出。</li><li><strong><a href="./troubleshooting.html">故障排查</a></strong> —— 常见问题与解决办法。</li><li><strong><a href="./donate.html">捐赠支持</a></strong> —— 如果 Lertaro 对你有帮助。</li></ul><p>如果是第一次配置 Lertaro，建议从<strong>快速上手</strong>开始阅读。</p>',5)])])}const m=r(s,[["render",n]]);export{p as __pageData,m as default};
